policies:
// Anyone authenticated may ask who they are.
@id("me")
permit(principal, action == Action::"Query.me", resource);

// Staff and billing readers may list invoices; which rows they see is decided per row below.
@id("list-invoices")
permit(principal, action == Action::"Query.invoices", resource)
when { principal in Group::"staff" || principal in Role::"billing-reader" };

// Row level: billing readers see every invoice, everyone else only their own.
@id("invoice-rows-billing")
permit(principal in Role::"billing-reader", action == Action::"Invoice.read", resource);
@id("invoice-rows-own")
permit(principal, action == Action::"Invoice.read", resource)
when { principal has email && resource has ownerEmail && resource.ownerEmail == principal.email };

// Field level: internal notes only for billing admins.
@id("invoice-notes")
permit(principal in Role::"billing-admin", action == Action::"Invoice.internalNotes", resource);

// Paying requires the admin role and a limit, and is never allowed through delegation.
@id("pay")
permit(principal in Role::"billing-admin", action == Action::"Mutation.payInvoice", resource)
when { context has amount && context.amount < 10000 };
@id("no-delegated-mutations")
forbid(principal, action, resource)
when { context has actor && context has operationType && context.operationType == "mutation" };
